export function median(values: number[]): number {
  if (!values.length) {
    throw new Error("median() requires at least one value")
  }

  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)

  return sorted.length % 2
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2
}

export function rawMAD(values: number[]): number {
  if (!values.length) {
    throw new Error("rawMAD() requires at least one value")
  }

  const med = median(values)
  const absoluteDeviations = values.map(v => Math.abs(v - med))

  return median(absoluteDeviations)
}

export function robustMADZ(
  score: number,
  baselineScores: number[],
  options?: {
    zeroMADFallback?: "zero" | "iqr" | "epsilon"
    epsilon?: number
    cap?: number
  }
): number {
  const {
    zeroMADFallback = "iqr",
    epsilon = 1e-9,
    cap = 8
  } = options ?? {}

  if (!Number.isFinite(score)) {
    throw new Error("score must be finite")
  }

  if (baselineScores.length < 3) {
    throw new Error("robustMADZ() requires at least 3 baseline scores")
  }

  const cleanBaseline = baselineScores.filter(Number.isFinite)

  if (cleanBaseline.length < 3) {
    throw new Error("robustMADZ() requires at least 3 finite baseline scores")
  }

  const med = median(cleanBaseline)
  let mad = rawMAD(cleanBaseline)

  if (mad === 0) {
    if (zeroMADFallback === "zero") return 0

    if (zeroMADFallback === "epsilon") {
      mad = epsilon
    }

    if (zeroMADFallback === "iqr") {
      const iqrScale = iqr(cleanBaseline) / 1.349
      mad = iqrScale > 0 ? iqrScale : epsilon
    }
  }

  const z = 0.6745 * (score - med) / mad

  return clamp(z, -cap, cap)
}

export function iqr(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b)
  return quantileSorted(sorted, 0.75) - quantileSorted(sorted, 0.25)
}

function quantileSorted(sorted: number[], q: number): number {
  if (!sorted.length) {
    throw new Error("quantileSorted() requires at least one value")
  }

  const pos = (sorted.length - 1) * q
  const base = Math.floor(pos)
  const rest = pos - base

  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base])
  }

  return sorted[base]
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max)
}
