export function robustMean(values: number[]): number {
  const clean = values.filter(Number.isFinite)

  if (!clean.length) return 0
  if (clean.length <= 2) return clean.reduce((a, b) => a + b, 0) / clean.length

  const sorted = [...clean].sort((a, b) => a - b)

  // Trim highest and lowest 20%
  const trimCount = Math.floor(sorted.length * 0.2)
  const trimmed = sorted.slice(trimCount, sorted.length - trimCount)

  const usable = trimmed.length ? trimmed : sorted

  return usable.reduce((a, b) => a + b, 0) / usable.length
}
